    bool initial=toggle->isChecked();touch.press(0,at(toggle),&panel).commit();settle();check(toggle->isChecked()==initial&&toggle->isDown(),"touch press activated or lost feedback");touch.release(0,at(toggle),&panel).commit();settle();check(toggle->isChecked()!=initial&&!toggle->isDown(),"touch release failed to toggle exactly once");
    initial=toggle->isChecked();auto outside=at(toggle)+QPoint(toggle->width(),0);touch.press(0,at(toggle),&panel).commit();touch.move(0,outside,&panel).commit();touch.move(0,at(toggle),&panel).commit();touch.release(0,at(toggle),&panel).commit();settle();check(toggle->isChecked()==initial,"slide-off returned to accidental activation");
