    const QPoint center=toggle->rect().center();const QPoint global=toggle->mapToGlobal(center);QMouseEvent down(QEvent::MouseButtonPress,center,center,global,Qt::LeftButton,Qt::LeftButton,Qt::NoModifier,Qt::MouseEventSynthesizedByQt),up(QEvent::MouseButtonRelease,center,center,global,Qt::LeftButton,Qt::NoButton,Qt::NoModifier,Qt::MouseEventSynthesizedByQt);QApplication::sendEvent(toggle,&down);QApplication::sendEvent(toggle,&up);check(toggle->isChecked()==initial,"synthesized mouse duplicated touch action");
