    panel.setPalette(app.palette());StepsRequest paletteRegression;paletteRegression.operation="derivative";paletteRegression.expression="1/(x+1)+sqrt(x)";panel.setRequest(paletteRegression);button("stepsDerive")->click();settle();const auto authoritative=qvariant_cast<QPalette>(panel.property("twPalette"));const auto expectedColors=TouchWorkbench::colors(authoritative);check(expectedColors.dark,"authoritative dark fixture was lost");for(auto*w:panel.findChildren<QWidget*>())if(auto*m=dynamic_cast<MathEditor*>(w)){check(m->palette().color(QPalette::Base)==expectedColors.surface,"new math card trusted QSS-mutated exposed palette");check(m->palette().color(QPalette::Text)==expectedColors.text||m->palette().color(QPalette::Text)==expectedColors.accent,"new math card ignored selected skin ink");}check(panel.findChild<QScrollArea*>("derivationScroll")->viewport()->palette().color(QPalette::Window)==expectedColors.background,"reading viewport trusted QSS-mutated exposed palette");panel.resize(360,800);settle();check(panel.grab().toImage().pixelColor(1,1)==expectedColors.background,"outer Steps surface trusted QSS-mutated exposed palette");check(dynamic_cast<MathEditor*>(panel.findChild<QWidget*>("stepsResultMath"))->grab().toImage().pixelColor(0,0)==expectedColors.surface,"new result math did not paint authoritative skin surface");capture("steps-dark-dynamic-result-360x800");
    TouchWorkbench::apply(&panel,app.palette());panel.resize(360,800);button("stepsEdit")->click();settle();capture("steps-setup-360x800");
