    auto*cancel=button("stepsCancel");for(auto*area:panel.findChildren<QScrollArea*>())if(area->isVisible())area->ensureWidgetVisible(cancel);settle();touch.press(0,at(cancel),&panel).commit();check(cancels==0,"cancel fired on press");touch.release(0,at(cancel),&panel).commit();settle();check(cancels==1&&!button("stepsCancel")->isVisible(),"touch cancellation did not complete");
    auto stale=StepsEngine::derive(pending);panel.setResult(stale);check(!panel.property("derivationReady").toBool(),"cancelled generation overwrote current view");panel.onDeriveRequested=derive;
    StepsRequest unsupported;unsupported.operation="solve";unsupported.expression="sin(x)=x";panel.setRequest(unsupported);button("stepsDerive")->click();settle();check(!panel.property("derivationReady").toBool()&&panel.findChild<QLabel*>("stepsStatus")->isVisible(),"unsupported problem fabricated steps or hid explanation");capture("steps-unsupported-360x800");
    for(const auto&fixture:QVector<QPair<QString,QString>>{{"derivative","1/(x+1)+sqrt(x)"},{"inverse","[1,2;3,4]"},{"inequality","(x-1)/(x+2)>=0"}}){StepsRequest r;r.operation=fixture.first;r.expression=fixture.second;panel.setRequest(r);button("stepsDerive")->click();settle();check(panel.property("derivationReady").toBool(),"native math fixture failed");capture("steps-"+fixture.first+"-360x800");}
    for(QString lang:locales)if(lang!="en")for(const char*label:{"Edit","More","Edit problem","More actions","Back","Supported problems","Return to steps","Expand / collapse all"})check(StepsLocalization::text(label,lang)!=QString::fromUtf8(label),"new caption untranslated");
    const QVector<QPair<QString,QString>> localizedCases={{"factor","x^2-1"},{"factor","x^2+1"},{"solve","2*x+1=0"},{"solve","x^2-3*x+2=0"},{"solve","0*x=1"},{"solve","abs(x)=x"},{"solve","sqrt(x+1)=x-1"},{"recurring","0.1(6)"},{"inequality","(x-1)/(x+2)>=0"},{"derivative","1/x+ln(x)+x^3"},{"integral","2*x*cos(x^2)+x*exp(x)+1/(2*x+1)+sin(2*x)+x^2"},{"limit","sin(x)/x"},{"limit","1/x"},{"inverse","[1,2;3,4]"},{"inverse","[1,2;2,4]"},{"rref","[0,2;3,4]"}};
